import type { Meta, StoryObj } from "@storybook/vue3";
import { h } from "vue";
import { KozmosLabel, KozmosTextarea } from "../../index";

/**
 * Vue's Textarea: the stories React's has, with the same names, each drawn
 * as React's story draws it, inside the KozmosThemeProvider the
 * Storybook's decorator gives every story. test/parity/textarea.parity.spec.ts
 * draws each in both and holds Vue's render to React's. Generated by `port
 * Textarea`; the stories React draws by hand written by hand.
 */
type Args = Record<string, unknown>;

const meta: Meta<Args> = {
  title: "Vue/Core/Inputs/Textarea",
  component: KozmosTextarea,
  parameters: { layout: "centered" },
};

export default meta;
type Story = StoryObj<Args>;

export const Default: Story = {
  render: () => ({
    setup: () => () =>
      h("div", { class: "grid w-full gap-1.5" }, [
        h(KozmosLabel, { for: "message" }, () => "Your message"),
        h(KozmosTextarea, {
          placeholder: "Type your message here.",
          id: "message",
        }),
      ]),
  }),
};

export const WithError: Story = {
  render: () => ({
    setup: () => () =>
      h("div", { class: "grid w-full gap-1.5" }, [
        h(KozmosLabel, { for: "message-error" }, () => "Your message"),
        // error draws the edge, the text and the focus ring, and sets
        // aria-invalid: a class here never lands in Safari 26.0 to 26.3,
        // which apply no @scope rule to a <textarea> (GAP-174).
        h(KozmosTextarea, {
          placeholder: "Type your message here.",
          id: "message-error",
          error: true,
        }),
        h(
          "span",
          { class: "text-sm font-medium text-destructive-text" },
          "Message cannot be empty.",
        ),
      ]),
  }),
};

/**
 * A character count, in all four states the MAP-474 feedback flow draws.
 * `limit` is a soft maximum, deliberately not `maxlength`; `minimum` only
 * applies once something has been typed. The count is never in the
 * `role="alert"` element while it is only a count.
 */
export const CharacterCount: Story = {
  parameters: { layout: "padded" },
  render: () => ({
    setup: () => () =>
      h("div", { class: "flex max-w-[420px] flex-col gap-6" }, [
        h(KozmosTextarea, {
          count: { limit: 512, minimum: 50 },
          defaultValue: "",
          label: "Empty — unanswered, not yet wrong",
        }),
        h(KozmosTextarea, {
          count: { limit: 512, minimum: 50 },
          defaultValue:
            "I reached my destination with such ease and comfort, and the signage was clear.",
          label: "Long enough",
        }),
        h(KozmosTextarea, {
          count: { limit: 512, minimum: 50 },
          defaultValue: "I got lost while navigating.",
          label: "Too short",
        }),
        h(KozmosTextarea, {
          count: { limit: 60 },
          defaultValue:
            "Express Maps has completely revolutionized my travel experience and I could not do without it.",
          label: "Over the limit",
        }),
      ]),
  }),
};
